213			t.Fatalf("第 2 条公开范围 = %v，期望 public", got)
214		}
215		if got := r0["createdAt"]; got != gomokuRoom["createdAt"] {
216			t.Fatalf("五子棋创建时间 = %v，期望保持原值 %v", got, gomokuRoom["createdAt"])
217		}
218		if got := r1["createdAt"]; got != ludoRoom["createdAt"] {
219			t.Fatalf("飞行棋创建时间 = %v，期望保持原值 %v", got, ludoRoom["createdAt"])
220		}
221	
222		// 启动与只查询列表不应改写本地已有内容：重启 + 查询后文件逐字节不变。
223		if got := readDataFile(t, dataDir); !bytes.Equal(got, beforeStopFile) {
224			t.Fatalf("重启或查询列表改写了数据文件：\n得到: %s\n期望: %s", got, beforeStopFile)
225		}
226	
227		// 重启后再成功创建一个房间：只能在原记录之后追加，旧记录内容与相对顺序不变。
228		createStatus, third := postRoom(t, second.url,
229			`{"name":"重启后新开的飞行棋","game":"ludo","capacity":2,"turnSeconds":600}`)
230		if createStatus != http.StatusCreated {
231			t.Fatalf("重启后创建状态码 = %d，期望 201，响应: %v", createStatus, third)
232		}
233		thirdID, _ := third["id"].(string)
234		if thirdID == "" {
235			t.Fatal("重启后新房间编号为空")
236		}
237		if thirdID == gomokuID || thirdID == ludoID {
238			t.Fatalf("重启后新房间编号 %q 与已有编号重复", thirdID)
239		}
240	
241		finalStatus, finalRooms := getRooms(t, second.url)
242		if finalStatus != http.StatusOK {
243			t.Fatalf("追加后查询状态码 = %d，期望 200", finalStatus)
244		}
245		if len(finalRooms) != 3 {
246			t.Fatalf("追加后房间数量 = %d，期望 3（原 2 条 + 新 1 条，不得清空或重新编号）", len(finalRooms))
247		}
248		if !reflect.DeepEqual(finalRooms[:2], before) {
249			t.Fatalf("追加后旧记录的内容或相对顺序被改变：\n得到: %v\n期望: %v", finalRooms[:2], before)
250		}
251		if !reflect.DeepEqual(finalRooms[2], third) {
252			t.Fatalf("列表中的新记录与本次创建响应不一致：\n列表: %v\n响应: %v", finalRooms[2], third)
253		}
254	}
255	
256	// 历史记录带有备注、数组或嵌套对象等附带字段，或缺少当前表单使用的字段时，
257	// 正常停止并用同一目录重启后必须按原内容返回，不能仅因字段不完整而删除记录；
258	// 历史名称中的首尾空白也不能在重启加载时被二次“整理”。启动与只查询列表不改写文件；
259	// 重启后合法创建的房间追加在这些历史记录之后。
260	func TestRestartPreservesAncillaryFieldsAndIncompleteHistory(t *testing.T) {
261		dataDir := t.TempDir()
262		// 完整对象 + 多种附带字段（字符串备注、数组、嵌套对象）。
263		histFull := `{"id":"hist-note","name":" 历史备注房 ","game":"ludo","capacity":3,"turnSeconds":0,"status":"waiting","visibility":"public","createdAt":"2026-03-04T10:00:00Z","note":"别忘带棋盘","tags":["周赛","老友"],"extra":{"rank":2,"meta":{"keep":true}}}`
264		// 老版本遗留记录：缺少当前表单使用的 game/capacity/turnSeconds 等字段，仍须保留。
265		histPartial := `{"id":"legacy-incomplete","name":"缺少表单字段的老房间"}`
266		seed := seedRooms(t, dataDir, histFull, histPartial)
267	
268		// 第一轮服务（模拟写下这批数据的上一轮进程）：只查询，不改写、不删除。
269		first := startRestartServer(t, dataDir)
270		assertRoomsUnchanged(t, first.url, dataDir, seed)
271		first.stop(t)
272	
273		// 第二轮服务：重启后同样原样返回，启动与查询都不动磁盘文件。
274		second := startRestartServer(t, dataDir)
275		assertRoomsUnchanged(t, second.url, dataDir, seed)
276	
277		_, rooms := getRooms(t, second.url)
278		full, ok := rooms[0].(map[string]any)
279		if !ok {
280			t.Fatalf("历史完整记录不是对象: %v", rooms[0])
281		}
282		if got := full["name"]; got != " 历史备注房 " {
283			t.Fatalf("历史名称应原样返回（不在加载时二次去空白），实际: %v", got)
284		}
285		if got := full["note"]; got != "别忘带棋盘" {
286			t.Fatalf("备注字段应原样保留，实际: %v", got)
287		}
288		tags, ok := full["tags"].([]any)
289		if !ok || len(tags) != 2 || tags[0] != "周赛" || tags[1] != "老友" {
290			t.Fatalf("数组附带字段应原样保留，实际: %v", full["tags"])
291		}
292		extra, ok := full["extra"].(map[string]any)
293		if !ok {
294			t.Fatalf("嵌套对象附带字段缺失: %v", full["extra"])
295		}
296		if got := extra["rank"]; got != float64(2) {
297			t.Fatalf("嵌套对象的 rank 应原样保留，实际: %v", got)
298		}
299		meta, ok := extra["meta"].(map[string]any)
300		if !ok || meta["keep"] != true {
301			t.Fatalf("深层嵌套内容应原样保留，实际: %v", extra["meta"])
302		}
303		partial, ok := rooms[1].(map[string]any)
304		if !ok {
305			t.Fatalf("字段不完整的历史记录不是对象: %v", rooms[1])
306		}
307		if len(partial) != 2 || partial["id"] != "legacy-incomplete" || partial["name"] != "缺少表单字段的老房间" {
308			t.Fatalf("字段不完整的历史记录应原样保留、不能被补默认值或删除，实际: %v", partial)
309		}
310	
311		// 重启后合法创建：历史两条原位保留，新对象追加在最后，附带字段不丢。
312		createStatus, created := postRoom(t, second.url,
313			`{"name":"历史数据上的新房","game":"gomoku","capacity":2,"turnSeconds":30}`)
314		if createStatus != http.StatusCreated {
315			t.Fatalf("历史数据上创建状态码 = %d，期望 201，响应: %v", createStatus, created)
316		}
317		_, all := getRooms(t, second.url)
318		if len(all) != 3 {
319			t.Fatalf("创建后记录数量 = %d，期望 3（历史 2 条一条不少 + 新房 1 条）", len(all))
320		}
321		if !reflect.DeepEqual(all[:2], decodeRecords(t, seed)) {
322			t.Fatalf("创建后历史记录（含附带字段与缺字段记录）被改动：\n得到: %v", all[:2])
323		}
324		if !reflect.DeepEqual(all[2], created) {
325			t.Fatalf("新房间应作为最后一条且与创建响应一致：\n列表: %v\n响应: %v", all[2], created)
326		}
327	}
328	
329	// 正常停止后保留下来的数据已经损坏（被截断，或顶层是 null 而不是数组）时，
330	// 重启本身不应清空/替换数据；重启后的列表查询和合法创建都必须返回 500，
331	// error 明确指向房间数据的读取或解析失败，不能返回成功的空列表或新房间编号，
332	// 磁盘上的损坏内容逐字节保留。
333	func TestRestartFailsOnCorruptPersistedData(t *testing.T) {
334		t.Run("停止后数据被截断", func(t *testing.T) {
335			dataDir := t.TempDir()
336			first := startRestartServer(t, dataDir)
337			if st, body := postRoom(t, first.url, `{"name":"截断前五子棋","game":"gomoku","capacity":2,"turnSeconds":0}`); st != http.StatusCreated {
338				t.Fatalf("准备数据时创建状态码 = %d，期望 201，响应: %v", st, body)
339			}
340			if st, body := postRoom(t, first.url, `{"name":"截断前飞行棋","game":"ludo","capacity":3,"turnSeconds":45}`); st != http.StatusCreated {
341				t.Fatalf("准备数据时创建状态码 = %d，期望 201，响应: %v", st, body)
342			}
343			first.stop(t)
344	
345			// 模拟停止后落盘内容被截断：只保留前半截，整体无法解析为数组。
346			original := readDataFile(t, dataDir)
347			corrupt := bytes.Clone(original[:len(original)/2])
348			if err := os.WriteFile(filepath.Join(dataDir, "rooms.json"), corrupt, 0o644); err != nil {
349				t.Fatalf("写入截断数据失败: %v", err)
350			}
351	
352			// 进程能正常启动（启动不重置数据），但查询与合法创建都返回 500 且文件不动。
353			second := startRestartServer(t, dataDir)
354			assertCreateFailsOnUnreadableData(t, second.url, dataDir, corrupt)
355		})
356	
357		t.Run("停止后数据顶层为 null", func(t *testing.T) {
358			dataDir := t.TempDir()
359			first := startRestartServer(t, dataDir)
360			if st, body := postRoom(t, first.url, `{"name":"null 前的房间","game":"gomoku","capacity":2,"turnSeconds":0}`); st != http.StatusCreated {
361				t.Fatalf("准备数据时创建状态码 = %d，期望 201，响应: %v", st, body)
362			}
363			first.stop(t)
364	
365			// 模拟停止后保留内容被整体替换为 JSON null。
366			nullSeed := seedRaw(t, dataDir, "null\n")
367	
368			second := startRestartServer(t, dataDir)
369			// 复用既有断言：GET 与合法 POST 均 500、error 指向房间数据、无列表/编号、文件逐字节不变。
370			assertCreateFailsOnUnreadableData(t, second.url, dataDir, nullSeed)
371	
372			// null 不属于“没有房间”，error 还必须明确指出顶层必须是数组。
373			st, body := postRoom(t, second.url, `{"name":"null 上的复验房","game":"gomoku","capacity":2,"turnSeconds":30}`)
374			if st != http.StatusInternalServerError {
375				t.Fatalf("null 数据上创建状态码 = %d，期望 500，响应: %v", st, body)
376			}
377			errMsg, _ := body["error"].(string)
378			if !strings.Contains(errMsg, "数组") {
379				t.Fatalf("error 应明确说明房间数据必须是数组、null 不代表空列表，实际: %q", errMsg)
380			}
381		})
382	}
383	
384	// 真正的空数组仍表示没有房间：经历正常停止与同目录重启后，查询成功且列表为空，
385	// 启动与查询都不改写空数组文件；随后正常创建的第一条记录可以被查询到。
386	func TestRestartEmptyArrayRemainsEmptyThenCreate(t *testing.T) {
387		dataDir := t.TempDir()
388	
389		// 首次启动会把数据文件初始化为空数组。
390		first := startRestartServer(t, dataDir)
391		st, rooms := getRooms(t, first.url)
392		if st != http.StatusOK {
393			t.Fatalf("首次查询状态码 = %d，期望 200", st)
394		}
395		if len(rooms) != 0 {
396			t.Fatalf("首次查询房间数量 = %d，期望 0", len(rooms))
397		}
398		first.stop(t)
399		if got := readDataFile(t, dataDir); string(got) != "[]\n" {
400			t.Fatalf("首次启动应初始化为空数组文件，实际: %q", got)
401		}
402	
403		// 同目录重启：仍是成功的空列表，启动与查询都不得把空数组改写成别的内容。
404		second := startRestartServer(t, dataDir)
405		st, rooms = getRooms(t, second.url)
406		if st != http.StatusOK {
407			t.Fatalf("重启后查询状态码 = %d，期望 200", st)
408		}
409		if len(rooms) != 0 {
410			t.Fatalf("重启后空列表出现了房间，数量 = %d，期望 0", len(rooms))
411		}
412		if got := readDataFile(t, dataDir); string(got) != "[]\n" {
413			t.Fatalf("重启或查询空列表改写了数据文件，实际: %q", got)
414		}
415	
416		// 空列表上正常创建的第一条房间可以被查询到。
417		createStatus, created := postRoom(t, second.url,
418			`{"name":"空列表后的第一间","game":"ludo","capacity":3,"turnSeconds":0}`)
419		if createStatus != http.StatusCreated {
420			t.Fatalf("空列表上创建状态码 = %d，期望 201，响应: %v", createStatus, created)
421		}
422		if id, _ := created["id"].(string); id == "" {
423			t.Fatal("新房间编号为空")
424		}
425		st, rooms = getRooms(t, second.url)
426		if st != http.StatusOK || len(rooms) != 1 {
427			t.Fatalf("创建后查询状态码 = %d、数量 = %d，期望 200 与 1 条", st, len(rooms))
428		}
429		if !reflect.DeepEqual(rooms[0], created) {
430			t.Fatalf("列表中的第一条记录与创建响应不一致：\n列表: %v\n响应: %v", rooms[0], created)
431		}
432	}
