181	// 已有房间时，合法创建应成功追加，且原有记录（含附带字段）保持不变。
182	func TestCreateRoomAppendsToExistingRooms(t *testing.T) {
183		dataDir := t.TempDir()
184		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
185		baseURL := startServer(t, dataDir)
186	
187		status, created := postRoom(t, baseURL, `{"name":"  周末 五子棋 友谊赛  ","game":"gomoku","capacity":2,"turnSeconds":0}`)
188		if status != http.StatusCreated {
189			t.Fatalf("创建状态码 = %d，期望 201，响应: %v", status, created)
190		}
191	
192		id, _ := created["id"].(string)
193		if id == "" {
194			t.Fatal("新房间编号为空")
195		}
196		if id == "seed-alpha" || id == "seed-beta" {
197			t.Fatalf("新房间编号 %q 与已有编号重复", id)
198		}
199		if got, want := created["name"], "周末 五子棋 友谊赛"; got != want {
200			t.Fatalf("名称 = %v，期望 %q（仅去掉首尾空白，内部空格保留）", got, want)
201		}
202		if got := created["game"]; got != "gomoku" {
203			t.Fatalf("游戏 = %v，期望 gomoku", got)
204		}
205		if got := created["capacity"]; got != float64(2) {
206			t.Fatalf("人数 = %v，期望 2", got)
207		}
208		if got := created["turnSeconds"]; got != float64(0) {
209			t.Fatalf("每步时间 = %v，期望 0（不限时）", got)
210		}
211		if got := created["status"]; got != "waiting" {
212			t.Fatalf("状态 = %v，期望 waiting", got)
213		}
214		if got := created["visibility"]; got != "public" {
215			t.Fatalf("公开范围 = %v，期望 public", got)
216		}
217		createdAt, _ := created["createdAt"].(string)
218		if _, err := time.Parse(time.RFC3339, createdAt); err != nil {
219			t.Fatalf("创建时间 %q 不是有效的 RFC3339 时间: %v", createdAt, err)
220		}
221	
222		// 列表应包含同一条新记录，追加在原记录之后。
223		listStatus, rooms := getRooms(t, baseURL)
224		if listStatus != http.StatusOK {
225			t.Fatalf("GET /api/rooms 状态码 = %d，期望 200", listStatus)
226		}
227		if len(rooms) != 3 {
228			t.Fatalf("房间数量 = %d，期望 3（原有 2 条 + 新增 1 条）", len(rooms))
229		}
230		seedRecords := decodeRecords(t, seed)
231		if !reflect.DeepEqual(rooms[:2], seedRecords) {
232			t.Fatalf("原有房间被改写或重新排序：\n得到: %v\n期望: %v", rooms[:2], seedRecords)
233		}
234		last, ok := rooms[2].(map[string]any)
235		if !ok {
236			t.Fatalf("新记录不是对象: %v", rooms[2])
237		}
238		if !reflect.DeepEqual(last, created) {
239			t.Fatalf("列表中的新记录与创建响应不一致：\n列表: %v\n响应: %v", last, created)
240		}
241		if got := last["turnSeconds"]; got != float64(0) {
242			t.Fatalf("列表中新记录的每步时间 = %v，期望 0（不限时）", got)
243		}
244	}
