512	// 整份数据是 JSON null 时，null 不表示“还没有房间”：公开约定要求顶层必须是
513	// 数组，只有空数组才表示没有记录。查询必须返回 500（不能返回成功的 rooms 内容），
514	// 合法创建同样必须返回 500 且原因落在已保存的房间数据上；文件内容逐字节保留，
515	// 不能被替换为空数组、追加房间或改写周围空白。null 前后的合法 JSON 空白一视同仁。
516	func TestRoomsFailWhenDataIsNull(t *testing.T) {
517		cases := []struct {
518			name    string
519			content string
520		}{
521			{"仅 null", "null\n"},
522			{"null 前后带合法 JSON 空白", " \t null \r\n"},
523			{"制表符与换行包围的 null", "\t\nnull\n\t"},
524		}
525		for _, tc := range cases {
526			t.Run(tc.name, func(t *testing.T) {
527				dataDir := t.TempDir()
528				seed := seedRaw(t, dataDir, tc.content)
529				baseURL := startServer(t, dataDir)
530	
531				assertCreateFailsOnUnreadableData(t, baseURL, dataDir, seed)
532	
533				// 失败信息必须明确指出房间数据必须是数组，与输入类错误区分开。
534				status, body := postRoom(t, baseURL, `{"name":"null 数据复验房","game":"gomoku","capacity":2,"turnSeconds":30}`)
535				if status != http.StatusInternalServerError {
536					t.Fatalf("再次创建状态码 = %d，期望 500，响应: %v", status, body)
537				}
538				errMsg, _ := body["error"].(string)
539				if !strings.Contains(errMsg, "数组") {
540					t.Fatalf("error 应明确说明房间数据必须是数组，实际: %q", errMsg)
541				}
542				if strings.Contains(errMsg, "缺少必填字段") || strings.Contains(errMsg, "不能为空") {
543					t.Fatalf("error 不应把格式错误归为用户漏填字段，实际: %q", errMsg)
