688	// 游戏规则与人数上限必须匹配：五子棋固定 2 人，飞行棋 2 至 4 人。
689	// 首页会随规则联动人数选项，但直接调用接口的请求不经过页面，
690	// 因此服务端必须独立完成同样的校验。下面验证所有允许的组合都能
691	// 按提交值保存（飞行棋 2/3/4 人不能都被存成 2），新房间追加在
692	// 原有记录之后，列表中的规则与人数和创建响应一致。
693	func TestCreateRoomGameCapacityCombinations(t *testing.T) {
694		dataDir := t.TempDir()
695		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
696		baseURL := startServer(t, dataDir)
697	
698		cases := []struct {
699			name     string
700			game     string
701			capacity int
702			turn     int
703		}{
704			{"周末五子棋", "gomoku", 2, 0},
705			{"双人飞行棋", "ludo", 2, 30},
706			{"三人飞行棋", "ludo", 3, 60},
707			{"四人飞行棋", "ludo", 4, 600},
708		}
709	
710		createdRooms := make([]map[string]any, 0, len(cases))
711		for _, tc := range cases {
712			body, _ := json.Marshal(map[string]any{
713				"name": "  " + tc.name + "  ", "game": tc.game,
714				"capacity": tc.capacity, "turnSeconds": tc.turn,
715			})
716			status, created := postRoom(t, baseURL, string(body))
717			if status != http.StatusCreated {
718				t.Fatalf("%s %d 人创建状态码 = %d，期望 201，响应: %v", tc.game, tc.capacity, status, created)
719			}
720			if id, _ := created["id"].(string); id == "" {
721				t.Fatalf("%s %d 人的新房间编号为空", tc.game, tc.capacity)
722			}
723			if got := created["game"]; got != tc.game {
724				t.Fatalf("规则 = %v，期望 %q（与本次提交一致）", got, tc.game)
725			}
726			if got := created["capacity"]; got != float64(tc.capacity) {
727				t.Fatalf("人数 = %v，期望 %d（按提交值保存，不得改写）", got, tc.capacity)
728			}
729			if got := created["name"]; got != tc.name {
730				t.Fatalf("名称 = %v，期望 %q（仍按现有方式去掉首尾空白）", got, tc.name)
731			}
732			if got := created["turnSeconds"]; got != float64(tc.turn) {
733				t.Fatalf("每步时间 = %v，期望 %d（人数校验不得改变其他配置）", got, tc.turn)
734			}
735			if got := created["status"]; got != "waiting" {
736				t.Fatalf("状态 = %v，期望 waiting（未开始）", got)
737			}
738			if got := created["visibility"]; got != "public" {
739				t.Fatalf("公开范围 = %v，期望 public", got)
740			}
741			createdRooms = append(createdRooms, created)
742		}
743	
744		// 飞行棋三种人数必须分别保存为 2、3、4，不能都被存成 2。
745		seen := map[float64]bool{}
746		for _, created := range createdRooms {
747			if created["game"] == "ludo" {
748				cap, _ := created["capacity"].(float64)
749				seen[cap] = true
750			}
751		}
752		for _, want := range []float64{2, 3, 4} {
753			if !seen[want] {
754				t.Fatalf("飞行棋 %v 人未被按提交值保存，实际保存的人数: %v", want, seen)
755			}
756		}
757	
758		// 列表应在原有 2 条之后按创建次序追加 4 条新房间，
759		// 列表中每条的规则、人数与对应创建响应一致。
760		listStatus, rooms := getRooms(t, baseURL)
761		if listStatus != http.StatusOK {
762			t.Fatalf("GET /api/rooms 状态码 = %d，期望 200", listStatus)
763		}
764		if len(rooms) != 2+len(cases) {
765			t.Fatalf("房间数量 = %d，期望 %d（原有 2 条 + 新增 %d 条）", len(rooms), 2+len(cases), len(cases))
766		}
767		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
768			t.Fatalf("原有房间被改写或重新排序：\n得到: %v\n期望: %v", rooms[:2], want)
769		}
770		for i, created := range createdRooms {
771			if !reflect.DeepEqual(rooms[2+i], created) {
772				t.Fatalf("列表第 %d 条新记录与创建响应不一致：\n列表: %v\n响应: %v", i+1, rooms[2+i], created)
773			}
774		}
775	}
