777	// 与规则不匹配的人数必须被拒绝：五子棋提交 3 或 4 人、飞行棋提交 1 或 5 人，
778	// 返回 400 且 error 清楚说明该规则允许的人数，不得悄悄改成合法值后创建。
779	// 这些请求的名称与每步时间都合法，错误原因必须落在规则与人数上，
780	// 不得显示无关的名称或时间错误。已有房间的数量、次序、内容与附带字段保持原样，
781	// 本地文件不被改写；把人数改成允许的值再次提交则应正常创建，被拒配置不留记录。
782	func TestCreateRoomRejectsCapacityMismatchingGame(t *testing.T) {
783		dataDir := t.TempDir()
784		seed := seedRooms(t, dataDir, seedRecord1, seedRecord2)
785		baseURL := startServer(t, dataDir)
786	
787		cases := []struct {
788			game        string
789			capacity    int
790			wantErrPart []string // error 必须同时包含的片段，用于辨认具体原因
791			fixed       int      // 该规则下允许、用于修正后重发的人数
792		}{
793			{"gomoku", 3, []string{"五子棋", "2"}, 2},
794			{"gomoku", 4, []string{"五子棋", "2"}, 2},
795			{"ludo", 1, []string{"飞行棋", "2", "4"}, 2},
796			{"ludo", 5, []string{"飞行棋", "2", "4"}, 4},
797		}
798	
799		for _, tc := range cases {
800			// 名称与每步时间都合法，若报错只能是规则与人数不匹配。
801			body, _ := json.Marshal(map[string]any{
802				"name": "人数不匹配房", "game": tc.game,
803				"capacity": tc.capacity, "turnSeconds": 30,
804			})
805			status, rejected := postRoom(t, baseURL, string(body))
806			if status != http.StatusBadRequest {
807				t.Fatalf("%s %d 人状态码 = %d，期望 400，响应: %v", tc.game, tc.capacity, status, rejected)
808			}
809			errMsg, _ := rejected["error"].(string)
810			for _, part := range tc.wantErrPart {
811				if !strings.Contains(errMsg, part) {
812					t.Fatalf("%s %d 人的 error 应包含 %q 以说明该规则允许的人数，实际: %q", tc.game, tc.capacity, part, errMsg)
813				}
814			}
815			if strings.Contains(errMsg, "名称") || strings.Contains(errMsg, "时间") || strings.Contains(errMsg, "turnSeconds") {
816				t.Fatalf("名称与时间均合法，error 不应落在无关字段上，实际: %q", errMsg)
817			}
818			if _, ok := rejected["id"]; ok {
819				t.Fatalf("被拒绝的请求不应返回房间编号，实际: %v", rejected)
820			}
821		}
822	
823		// 全部拒绝后：房间数量、次序、内容及附带字段与种子一致，本地文件未被改写。
824		assertRoomsUnchanged(t, baseURL, dataDir, seed)
825	
826		// 把人数改成对应规则允许的值再次提交，应正常创建；被拒配置不留下任何记录。
827		for _, tc := range cases {
828			body, _ := json.Marshal(map[string]any{
829				"name": "人数不匹配房", "game": tc.game,
830				"capacity": tc.fixed, "turnSeconds": 30,
831			})
832			status, created := postRoom(t, baseURL, string(body))
833			if status != http.StatusCreated {
834				t.Fatalf("修正为 %s %d 人后创建状态码 = %d，期望 201，响应: %v", tc.game, tc.fixed, status, created)
835			}
836			if got := created["capacity"]; got != float64(tc.fixed) {
837				t.Fatalf("修正后保存的人数 = %v，期望 %d", got, tc.fixed)
838			}
839		}
840	
841		_, rooms := getRooms(t, baseURL)
842		if len(rooms) != 2+len(cases) {
843			t.Fatalf("房间数量 = %d，期望 %d（种子 2 条 + 修正后 %d 条，被拒配置不得留记录）", len(rooms), 2+len(cases), len(cases))
844		}
845		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
846			t.Fatalf("原有房间被改动：\n得到: %v\n期望: %v", rooms[:2], want)
847		}
848		for _, record := range rooms[2:] {
849			room, _ := record.(map[string]any)
850			if room["name"] == "人数不匹配房" {
851				game, _ := room["game"].(string)
852				cap := room["capacity"]
853				allowed := map[string][]float64{"gomoku": {2}, "ludo": {2, 3, 4}}[game]
854				ok := false
855				for _, a := range allowed {
856					if cap == a {
857						ok = true
858					}
859				}
860				if !ok {
861					t.Fatalf("列表中出现曾被拒绝的 %s %v 人配置，说明拒绝时被悄悄改成合法值或留下了记录", game, cap)
862				}
863			}
864		}
865	}
