883			{"人数为小数", `{"name":"小数人数房","game":"ludo","capacity":2.5,"turnSeconds":30}`, []string{"capacity", "整数"}},
884			{"人数为 null", `{"name":"null 人数房","game":"ludo","capacity":null,"turnSeconds":30}`, []string{"capacity", "整数"}},
