896				}
897			}
898			// 名称与每步时间都合法，错误原因只能落在人数字段上。
899			if strings.Contains(errMsg, "名称") || strings.Contains(errMsg, "turnSeconds") {
900				t.Fatalf("%s：名称与时间均合法，error 不应落在无关字段上，实际: %q", tc.desc, errMsg)
901			}
902			if _, ok := rejected["id"]; ok {
903				t.Fatalf("%s：被拒绝的请求不应返回房间编号，实际: %v", tc.desc, rejected)
904			}
