913		// 2.0 带小数点，不是整数字面量，同样按非整数拒绝，不能取整成 2 保存。
914		fractionalStatus, fractionalBody := postRoom(t, baseURL, `{"name":"复验小数","game":"gomoku","capacity":2.0,"turnSeconds":0}`)
915		if fractionalStatus != http.StatusBadRequest {
