921		}
922	
923		// 全部拒绝后：已有房间与本地文件保持原样。
924		assertRoomsUnchanged(t, baseURL, dataDir, seed)
925	
926		// 修正为合法整数后应正常创建，被拒请求不留下记录。
927		status, created := postRoom(t, baseURL, `{"name":"修正人数房","game":"ludo","capacity":3,"turnSeconds":30}`)
928		if status != http.StatusCreated {
929			t.Fatalf("修正后创建状态码 = %d，期望 201，响应: %v", status, created)
930		}
931		if got := created["capacity"]; got != float64(3) {
932			t.Fatalf("修正后保存的人数 = %v，期望 3", got)
933		}
934		_, rooms := getRooms(t, baseURL)
935		if len(rooms) != 3 {
936			t.Fatalf("房间数量 = %d，期望 3（种子 2 条 + 修正后 1 条，被拒请求不得留记录）", len(rooms))
937		}
938		if want := decodeRecords(t, seed); !reflect.DeepEqual(rooms[:2], want) {
939			t.Fatalf("原有房间被改动：\n得到: %v\n期望: %v", rooms[:2], want)
940		}
941	}
